type AdminIdentity = { id: string; fullName: string | null; email: string | null; phone: string | null };
type AdminResolver = (request: FastifyRequest) => Promise<AdminIdentity | null>;
type AnyBody = Record<string, unknown>;

type Section =
  | 'dashboard' | 'users' | 'social' | 'virtual' | 'premium' | 'topup' | 'accounts'
  | 'promotions' | 'orders' | 'payments' | 'coupons' | 'banners' | 'notifications'
  | 'support' | 'settings' | 'audit';

const esc = (value: unknown) => String(value ?? '')
  .replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;').replaceAll("'", '&#39;');
const text = (body: AnyBody, key: string) => String(body[key] ?? '').trim();
const checked = (body: AnyBody, key: string) => ['on', 'true', '1'].includes(String(body[key] ?? ''));
const num = (value: unknown, fallback = 0) => { const n = Number(value); return Number.isFinite(n) ? n : fallback; };
const int = (value: unknown, fallback = 0) => { const n = Number.parseInt(String(value ?? ''), 10); return Number.isFinite(n) ? n : fallback; };
const faDate = (value: Date | string | null | undefined) => value ? new Date(value).toLocaleString('fa-IR') : '—';
const afn = (value: bigint | number | string | null | undefined) => `${Number(value ?? 0).toLocaleString('en-US')} AFN`;
const shortId = (value: string) => value.slice(0, 8).toUpperCase();
const url = (section: Section, extra = '') => `/admin/v3?section=${section}${extra}`;
const badge = (label: string, kind = '') => `<span class="badge ${kind}">${esc(label)}</span>`;

