    wallet: '<path d="M3 6h16a2 2 0 0 1 2 2v10H3a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h14M16 12h5"/>',
    orders: '<path d="M6 2h12l2 5H4zM5 7h14v15H5zM9 11h6M9 15h6"/>',
