async function requireAdmin(request: FastifyRequest, reply: FastifyReply, resolveAdmin: AdminResolver) {
  const admin = await resolveAdmin(request);
  if (!admin) { reply.code(303).redirect('/admin'); return null; }
  return admin;
}

async function audit(prisma: PrismaClient, adminId: string, action: string, entityType: string, entityId: string | null, summary: string, metadata?: Prisma.InputJsonValue) {
  await prisma.adminAuditLog.create({ data: { adminUserId: adminId, action, entityType, entityId, summary, metadata } });
}

function queryState(request: FastifyRequest) {
  const q = (request.query ?? {}) as Record<string, unknown>;
  const allowed = new Set<Section>(['dashboard','users','social','virtual','premium','topup','accounts','promotions','orders','payments','coupons','banners','notifications','support','settings','audit']);
  const candidate = String(q.section ?? 'dashboard') as Section;
  return {
    section: allowed.has(candidate) ? candidate : 'dashboard' as Section,
    tab: String(q.tab ?? 'overview'), q: String(q.q ?? '').trim().slice(0, 120),
    edit: String(q.edit ?? '').trim(), ticket: String(q.ticket ?? '').trim(),
    msg: String(q.msg ?? '').trim(), err: String(q.err ?? '') === '1',
  };
}

function tabs(section: Section, current: string, items: [string,string][]) {
  return `<div class="tabs">${items.map(([key,label]) => `<a class="tab ${current === key ? 'active' : ''}" href="${url(section, `&tab=${encodeURIComponent(key)}`)}">${esc(label)}</a>`).join('')}</div>`;
}

function statusBadge(status: string) {
  const good = ['ACTIVE','COMPLETED','PAID','RESOLVED'];
  const bad = ['FAILED','SUSPENDED','CANCELLED','REFUNDED','CLOSED'];
  const warn = ['PENDING','PROCESSING','AWAITING_SMS','PARTIAL','PENDING_USER','PENDING_ADMIN'];
  return badge(status, good.includes(status) ? 'ok' : bad.includes(status) ? 'bad' : warn.includes(status) ? 'warn' : 'info');
}

function chartSvg(values: number[]) {
  const data = values.length ? values : [0];
  const max = Math.max(...data, 1);
  const points = data.map((v,i) => `${20 + (i * 660 / Math.max(1,data.length - 1))},${190 - (v / max) * 155}`).join(' ');
  const area = `${points} 680,205 20,205`;
  return `<svg class="chart" viewBox="0 0 700 220" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#1687f8" stop-opacity=".22"/><stop offset="1" stop-color="#1687f8" stop-opacity="0"/></linearGradient></defs><g class="chart-grid">${[45,85,125,165,205].map(y=>`<line x1="20" x2="680" y1="${y}" y2="${y}"/>`).join('')}</g><polygon class="chart-fill" points="${area}"/><polyline class="chart-line" points="${points}"/></svg>`;
}

async function providerHealth(provider: { id:string; name:string; kind:ProviderKind; enabled:boolean; secretCiphertext:string|null; baseUrl:string|null; priority:number; defaultMarkupPercent:Prisma.Decimal; timeoutSeconds:number; notes:string|null; slug:string }) {
  if (!provider.enabled) return { state: 'خاموش', cls: 'bad', balance: '—' };
  if (!provider.secretCiphertext) return { state: 'نیاز به API Key', cls: 'warn', balance: '—' };
  try {
    if (provider.kind === ProviderKind.SOCIAL) {
      const b = await smmClientForProvider(provider as any).balance();
      return { state: 'فعال', cls: 'ok', balance: `${b.balance} ${b.currency || ''}`.trim() };
    }
    if (provider.kind === ProviderKind.VIRTUAL_NUMBER) {
      const p = await fiveSimClientForProvider(provider as any).profile();
      return { state: 'فعال', cls: 'ok', balance: String(p.balance) };
    }
    return { state: 'فعال', cls: 'ok', balance: 'Configured' };
  } catch { return { state: 'خطای اتصال', cls: 'warn', balance: '—' }; }
}

async function dashboard(prisma: PrismaClient) {
  const now = new Date(); const start = new Date(now); start.setUTCHours(0,0,0,0);
  const from30 = new Date(now.getTime() - 29 * 86400000);
  const activeOrder = { notIn: [OrderStatus.CANCELLED, OrderStatus.FAILED, OrderStatus.REFUNDED] };
  const [totalUsers, ordersToday, salesTodayAgg, recent, rangeOrders, providers] = await Promise.all([
    prisma.user.count(),
    prisma.order.count({ where: { createdAt: { gte: start }, status: activeOrder } }),
    prisma.order.aggregate({ where: { createdAt: { gte: start }, status: activeOrder }, _sum: { totalAmountAfn: true, providerCostAfn: true } }),
    prisma.order.findMany({ include: { user: true, service: true }, orderBy: { createdAt: 'desc' }, take: 6 }),
    prisma.order.findMany({ where: { createdAt: { gte: from30 }, status: activeOrder }, select: { createdAt:true,totalAmountAfn:true,category:true } }),
    prisma.provider.findMany({ orderBy: [{ enabled:'desc' }, { priority:'asc' }], take: 6 }),
  ]);
  const sales = salesTodayAgg._sum.totalAmountAfn ?? 0n; const costs = salesTodayAgg._sum.providerCostAfn ?? 0n; const profit = sales - costs;
  const days = Array.from({length:30},(_,i)=>{const d=new Date(from30.getTime()+i*86400000);return d.toISOString().slice(0,10)});
  const dayMap = new Map(days.map(d=>[d,0])); const cat = new Map<string,number>();
  for (const o of rangeOrders) { const key=o.createdAt.toISOString().slice(0,10); dayMap.set(key,(dayMap.get(key)||0)+Number(o.totalAmountAfn)); cat.set(o.category,(cat.get(o.category)||0)+Number(o.totalAmountAfn)); }
  const totalCat=[...cat.values()].reduce((a,b)=>a+b,0)||1;
  const colors:Record<string,string>={SOCIAL:'#1687f8',VIRTUAL_NUMBER:'#13bf91',PREMIUM:'#6bd67f',MOBILE_TOPUP:'#f3a11d',DIGITAL_ACCOUNT:'#7b61ff',PROMOTION:'#ed5571'};
  let acc=0; const seg=[...cat.entries()].map(([k,v])=>{const start=acc;acc+=v/totalCat*100;return `${colors[k]||'#9aa8b8'} ${start}% ${acc}%`;}).join(',');
  const health = await Promise.all(providers.map(async p => ({ p, h: await providerHealth(p as any) })));
  return `<div class="stats"><div class="stat"><div class="stat-icon">${icon('users')}</div><div class="stat-copy"><small>کل کاربران</small><strong>${totalUsers.toLocaleString('en-US')}</strong><div class="delta">داده زنده</div></div></div><div class="stat"><div class="stat-icon">${icon('orders')}</div><div class="stat-copy"><small>سفارش‌های امروز</small><strong>${ordersToday.toLocaleString('en-US')}</strong><div class="delta">امروز</div></div></div><div class="stat"><div class="stat-icon">${icon('wallet')}</div><div class="stat-copy"><small>فروش امروز</small><strong>${afn(sales)}</strong><div class="delta">بر اساس سفارش‌های معتبر</div></div></div><div class="stat"><div class="stat-icon">${icon('dashboard')}</div><div class="stat-copy"><small>سود خالص ثبت‌شده</small><strong>${afn(profit)}</strong><div class="delta">فروش منهای هزینه Provider</div></div></div></div><div class="grid"><div class="card"><div class="card-head"><div><h2>نمودار فروش</h2><span class="muted">۳۰ روز گذشته</span></div><div class="actions">${badge('روزانه','info')}${badge('زنده')}</div></div>${chartSvg([...dayMap.values()])}</div><div class="card"><div class="card-head"><h2>سهم خدمات</h2><span class="muted">۳۰ روز</span></div><div class="donut-wrap"><div class="donut" style="background:conic-gradient(${seg || '#e6eef6 0 100%'})"><div class="donut-center">کل فروش<b>${afn([...dayMap.values()].reduce((a,b)=>a+b,0))}</b></div></div><div class="legend">${[...cat.entries()].sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="legend-row"><i class="dot" style="background:${colors[k]||'#9aa8b8'}"></i><span>${esc(k.replaceAll('_',' '))}</span><b>${Math.round(v/totalCat*100)}%</b></div>`).join('') || '<span class="muted">هنوز فروش ثبت نشده است.</span>'}</div></div></div></div><div class="grid"><div class="card"><div class="card-head"><h2>آخرین سفارش‌ها</h2><a class="link" href="${url('orders')}">مشاهده همه</a></div><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>کاربر</th><th>خدمت</th><th>مبلغ</th><th>وضعیت</th><th>زمان</th></tr></thead><tbody>${recent.map(o=>`<tr><td>${shortId(o.id)}</td><td>${esc(o.user.fullName||o.user.email||o.user.phone||'—')}</td><td><b>${esc(o.service?.titleFa||o.category)}</b></td><td class="money">${afn(o.totalAmountAfn)}</td><td>${statusBadge(o.status)}</td><td>${faDate(o.createdAt)}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">هنوز سفارشی نیست.</td></tr>'}</tbody></table></div></div><div class="card"><div class="card-head"><h2>وضعیت ارائه‌دهندگان</h2><a class="link" href="${url('social','&tab=providers')}">مدیریت</a></div><div class="providers">${health.map(({p,h})=>`<div class="provider-row"><div class="provider-logo">${esc(p.name.charAt(0).toUpperCase())}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.kind.replaceAll('_',' '))} Provider</small></div>${badge(h.state,h.cls)}<div class="money">${esc(h.balance)}</div></div>`).join('') || '<div class="empty">ارائه‌دهنده‌ای ثبت نشده است.</div>'}</div></div></div>`;
}

async function usersPage(prisma: PrismaClient, q: string, edit: string) {
  const where: Prisma.UserWhereInput = q ? { OR:[{fullName:{contains:q,mode:'insensitive'}},{email:{contains:q,mode:'insensitive'}},{phone:{contains:q,mode:'insensitive'}}] } : {};
  const [users,total,selected] = await Promise.all([
    prisma.user.findMany({ where, include:{wallet:true}, orderBy:{createdAt:'desc'}, take:100 }), prisma.user.count({where}),
    edit ? prisma.user.findUnique({where:{id:edit},include:{wallet:{include:{entries:{orderBy:{createdAt:'desc'},take:12}}}}}) : Promise.resolve(null),
  ]);
  return `<div class="card"><div class="card-head"><div><h2>کاربران</h2><span class="muted">${total.toLocaleString('en-US')} حساب</span></div><form method="get" action="/admin/v3" class="actions"><input type="hidden" name="section" value="users"><input name="q" value="${esc(q)}" placeholder="نام، ایمیل یا شماره" style="height:35px;border:1px solid #e3ebf4;border-radius:8px;padding:0 9px"><button class="btn" type="submit">جستجو</button></form></div><div class="table-wrap"><table class="table"><thead><tr><th>کاربر</th><th>نقش</th><th>وضعیت</th><th>کیف پول</th><th>تاریخ عضویت</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><b>${esc(u.fullName||'—')}</b><br><span class="muted">${esc(u.email||u.phone||'—')}</span></td><td>${badge(u.role,u.role==='ADMIN'?'info':'')}</td><td>${statusBadge(u.status)}</td><td class="money">${afn(u.wallet?.balanceAfn||0n)}</td><td>${faDate(u.createdAt)}</td><td><a class="btn ghost" href="${url('users',`&edit=${u.id}`)}">مدیریت</a></td></tr>`).join('')}</tbody></table></div></div>${selected?`<div class="grid equal"><div class="card"><div class="card-head"><h2>مدیریت ${esc(selected.fullName||'کاربر')}</h2>${statusBadge(selected.status)}</div><form method="post" action="/admin/v3/user/status"><input type="hidden" name="userId" value="${selected.id}"><input type="hidden" name="returnTo" value="users&edit=${selected.id}"><div class="form-grid"><div class="field"><label>نقش</label><select name="role"><option ${selected.role==='USER'?'selected':''}>USER</option><option ${selected.role==='ADMIN'?'selected':''}>ADMIN</option></select></div><div class="field"><label>وضعیت</label><select name="status"><option ${selected.status==='ACTIVE'?'selected':''}>ACTIVE</option><option ${selected.status==='SUSPENDED'?'selected':''}>SUSPENDED</option></select></div></div><button class="btn">ذخیره حساب</button></form><hr style="border:0;border-top:1px solid #edf2f7;margin:16px 0"><form method="post" action="/admin/v3/wallet"><input type="hidden" name="userId" value="${selected.id}"><input type="hidden" name="returnTo" value="users&edit=${selected.id}"><div class="form-grid"><div class="field"><label>تغییر موجودی AFN</label><input name="amountAfn" type="number" placeholder="500 یا -200" required></div><div class="field"><label>دلیل</label><input name="reason" minlength="3" required placeholder="دلیل تغییر"></div></div><button class="btn">ثبت در Ledger</button></form></div><div class="card"><div class="card-head"><h2>تراکنش‌های اخیر</h2><b class="money">${afn(selected.wallet?.balanceAfn||0n)}</b></div>${selected.wallet?.entries.map(e=>`<div class="provider-row" style="grid-template-columns:1fr auto"><div><strong>${esc(e.description||e.type)}</strong><small>${faDate(e.createdAt)}</small></div><div class="money" style="color:${e.amountAfn>=0n?'#19a873':'#e65362'}">${e.amountAfn>0n?'+':''}${afn(e.amountAfn)}</div></div>`).join('')||'<div class="empty">تراکنشی نیست.</div>'}</div></div>`:''}`;
}

function providerForm(kind: ProviderKind, section: Section, provider?: any) {
  return `<form method="post" action="/admin/v3/provider/save"><input type="hidden" name="providerId" value="${esc(provider?.id||'')}"><input type="hidden" name="kind" value="${kind}"><input type="hidden" name="section" value="${section}"><div class="form-grid"><div class="field"><label>نام ارائه‌دهنده</label><input name="name" value="${esc(provider?.name||'')}" required placeholder="JustAnotherPanel"></div><div class="field"><label>Slug</label><input class="code" name="slug" value="${esc(provider?.slug||'')}" required placeholder="justanotherpanel"></div><div class="field"><label>API Base URL</label><input class="code" name="baseUrl" value="${esc(provider?.baseUrl||'')}" placeholder="https://provider.example/api/v2"></div><div class="field"><label>اولویت (کمتر = بالاتر)</label><input name="priority" type="number" value="${esc(provider?.priority??20)}"></div><div class="field"><label>Markup پیش‌فرض %</label><input name="markup" inputmode="decimal" value="${esc(provider?.defaultMarkupPercent?.toString?.()||'0')}"></div><div class="field"><label>Timeout (ثانیه)</label><input name="timeout" type="number" min="5" max="120" value="${esc(provider?.timeoutSeconds??30)}"></div></div><div class="field"><label>یادداشت داخلی</label><textarea name="notes">${esc(provider?.notes||'')}</textarea></div><label class="check"><input type="checkbox" name="enabled" ${provider?.enabled===false?'':'checked'}> فعال باشد</label><button class="btn" type="submit">${provider?'ذخیره تغییرات':'افزودن ارائه‌دهنده'}</button></form>`;
}

async function providerModule(prisma: PrismaClient, section: Section, category: ServiceCategory, kind: ProviderKind, tab: string, q: string, edit: string) {
  const moduleTabs = tabs(section,tab,[['overview','نمای کلی'],['providers','ارائه‌دهندگان'],['services','سرویس‌ها'],['orders','سفارش‌ها'],['logs','API Logs']]);
  const [providers,services,orders] = await Promise.all([
    prisma.provider.findMany({where:{kind},orderBy:[{enabled:'desc'},{priority:'asc'}]}),
    prisma.service.findMany({where:{category,...(q?{OR:[{titleFa:{contains:q,mode:'insensitive'}},{titleEn:{contains:q,mode:'insensitive'}},{slug:{contains:q,mode:'insensitive'}}]}:{})},include:{routes:{include:{provider:true},orderBy:{priority:'asc'}}},orderBy:[{enabled:'desc'},{sortOrder:'asc'}],take:250}),
    prisma.order.findMany({where:{category},include:{user:true,service:true,provider:true,actions:{orderBy:{createdAt:'desc'},take:2}},orderBy:{createdAt:'desc'},take:100}),
  ]);
  const editing = edit ? providers.find(p=>p.id===edit) : undefined;
  let body='';
  if(tab==='providers') body=`<div class="grid"><div><div class="card"><div class="card-head"><h2>ارائه‌دهندگان ${esc(sectionMeta[section][0])}</h2>${badge(`${providers.length} Provider`,'info')}</div><div class="providers">${providers.map(p=>`<div class="provider-row"><div class="provider-logo">${esc(p.name.charAt(0))}</div><div><strong>${esc(p.name)}</strong><small class="code">${esc(p.baseUrl||'No URL')}</small></div>${p.enabled?badge('فعال','ok'):badge('خاموش','bad')}<div class="actions"><a class="btn ghost" href="${url(section,`&tab=providers&edit=${p.id}`)}">ویرایش</a></div></div>`).join('')||'<div class="empty">ارائه‌دهنده‌ای ثبت نشده است.</div>'}</div></div>${editing?`<div class="card"><div class="card-head"><h2>Secret / API Key</h2>${editing.secretCiphertext?badge('Configured','ok'):badge('Not configured','warn')}</div><p class="muted">کلید ذخیره‌شده هرگز نمایش داده نمی‌شود و با AES-256-GCM رمزگذاری می‌شود.</p><form method="post" action="/admin/v3/provider/secret"><input type="hidden" name="providerId" value="${editing.id}"><input type="hidden" name="section" value="${section}"><div class="field"><label>API Key / Token جدید</label><textarea class="code" name="secret" required placeholder="API key یا JSON secret"></textarea></div><button class="btn">ذخیره امن کلید</button></form></div>`:''}</div><div class="card"><div class="card-head"><h2>${editing?'ویرایش Provider':'Provider جدید'}</h2><span class="muted">داخل همین ماژول مدیریت می‌شود</span></div>${providerForm(kind,section,editing)}</div></div>`;
  else if(tab==='services') body=`<div class="card"><div class="card-head"><div><h2>سرویس‌های مشتری</h2><span class="muted">نام Provider برای مشتری مخفی است؛ Routeها داخل این پنل مدیریت می‌شوند.</span></div><form method="get" action="/admin/v3" class="actions"><input type="hidden" name="section" value="${section}"><input type="hidden" name="tab" value="services"><input name="q" value="${esc(q)}" placeholder="جستجوی سرویس" style="height:35px;border:1px solid #e3ebf4;border-radius:8px;padding:0 9px"><button class="btn">جستجو</button></form></div><div class="table-wrap"><table class="table"><thead><tr><th>سرویس</th><th>Route / Provider</th><th>قیمت</th><th>محدوده</th><th>وضعیت</th><th>کنترل</th></tr></thead><tbody>${services.map(s=>`<tr><td><b>${esc(s.titleFa)}</b><br><span class="muted">${esc(s.titleEn)}</span><br><span class="code muted">${esc(s.slug)}</span></td><td>${s.routes.map(r=>`${esc(r.provider.name)} · <span class="code">${esc(r.providerServiceCode)}</span>`).join('<br>')||'—'}</td><td class="money">${s.basePriceAfn!=null?afn(s.basePriceAfn):'Auto markup'}</td><td>${s.minQty??'—'} – ${s.maxQty??'—'}</td><td>${s.enabled?badge('فعال','ok'):badge('خاموش','bad')}</td><td><form method="post" action="/admin/v3/service/toggle"><input type="hidden" name="serviceId" value="${s.id}"><input type="hidden" name="section" value="${section}"><input type="hidden" name="enabled" value="${s.enabled?'0':'1'}"><button class="btn ghost">${s.enabled?'غیرفعال':'فعال'}</button></form></td></tr>`).join('')||'<tr><td colspan="6" class="empty">سرویسی نیست.</td></tr>'}</tbody></table></div></div>`;
  else if(tab==='orders') body=ordersTable(orders);
  else if(tab==='logs') { const ids=orders.map(o=>o.id); const logs=ids.length?await prisma.orderActionLog.findMany({where:{orderId:{in:ids}},include:{order:true},orderBy:{createdAt:'desc'},take:150}):[]; body=`<div class="card"><div class="card-head"><h2>API / Action Logs</h2><span class="muted">آخرین تعاملات سفارش با Provider</span></div><div class="table-wrap"><table class="table"><thead><tr><th>زمان</th><th>سفارش</th><th>عملیات</th><th>وضعیت</th><th>Provider Ref</th></tr></thead><tbody>${logs.map(l=>`<tr><td>${faDate(l.createdAt)}</td><td>${shortId(l.orderId)}</td><td>${esc(l.action)}</td><td>${statusBadge(l.status)}</td><td class="code">${esc(l.providerReference||'—')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Log ثبت نشده است.</td></tr>'}</tbody></table></div></div>`; }
  else body=`<div class="card module-hero"><div class="card-head"><div><h2>${esc(sectionMeta[section][0])}</h2><p>تمام Providerها، سرویس‌ها و سفارش‌های این بخش در یک ماژول مستقل مدیریت می‌شوند.</p></div>${icon(section==='virtual'?'virtual':'services')}</div><div class="kpis"><div><b>${providers.length}</b><small>ارائه‌دهنده</small></div><div><b>${services.length}</b><small>سرویس</small></div><div><b>${orders.length}</b><small>سفارش اخیر</small></div><div><b>${services.filter(s=>s.enabled).length}</b><small>سرویس فعال</small></div></div></div><div class="grid equal"><div class="card"><div class="card-head"><h2>ارائه‌دهندگان</h2><a class="link" href="${url(section,'&tab=providers')}">مدیریت</a></div>${providers.slice(0,8).map(p=>`<div class="provider-row"><div class="provider-logo">${esc(p.name.charAt(0))}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.kind)}</small></div>${p.enabled?badge('فعال','ok'):badge('خاموش','bad')}<span class="muted">P${p.priority}</span></div>`).join('')||'<div class="empty">Provider ندارد.</div>'}</div><div class="card"><div class="card-head"><h2>آخرین سفارش‌ها</h2><a class="link" href="${url(section,'&tab=orders')}">مشاهده همه</a></div>${orders.slice(0,6).map(o=>`<div class="provider-row" style="grid-template-columns:1fr auto auto"><div><strong>${esc(o.service?.titleFa||o.category)}</strong><small>${esc(o.user.fullName||o.user.email||'—')} · ${faDate(o.createdAt)}</small></div>${statusBadge(o.status)}<b class="money">${afn(o.totalAmountAfn)}</b></div>`).join('')||'<div class="empty">سفارشی نیست.</div>'}</div></div>`;
  return { tabs: moduleTabs, body };
}

async function socialPage(prisma: PrismaClient, tab:string,q:string,edit:string) {
  if(!['categories','routing'].includes(tab)) return providerModule(prisma,'social',ServiceCategory.SOCIAL,ProviderKind.SOCIAL,tab,q,edit);
  const moduleTabs=tabs('social',tab,[['overview','نمای کلی'],['providers','ارائه‌دهندگان'],['categories','دسته‌بندی‌ها'],['services','سرویس‌ها'],['routing','Routing'],['orders','سفارش‌ها'],['logs','API Logs']]);
  if(tab==='categories') { const rows=await prisma.systemSetting.findMany({where:{category:'social-category'},orderBy:{key:'asc'}}); const grouped=await prisma.service.groupBy({by:['socialPlatform','socialGroup'],where:{category:ServiceCategory.SOCIAL},_count:{_all:true}}); return {tabs:moduleTabs,body:`<div class="grid equal"><div class="card"><div class="card-head"><h2>دسته‌بندی‌های تعریف‌شده</h2>${badge(`${rows.length} دسته`,'info')}</div>${rows.map(r=>`<div class="provider-row" style="grid-template-columns:1fr auto"><div><strong>${esc(r.key.replace('social.category.',''))}</strong><small>${esc(JSON.stringify(r.value).slice(0,140))}</small></div>${badge('سیستمی')}</div>`).join('')||'<div class="empty">دسته سفارشی ثبت نشده است.</div>'}</div><div class="card"><div class="card-head"><h2>دسته‌بندی خودکار سرویس‌ها</h2><span class="muted">از Catalog Provider</span></div>${grouped.map(g=>`<div class="provider-row" style="grid-template-columns:1fr auto"><div><strong>${esc(g.socialPlatform||'OTHER')} / ${esc(g.socialGroup||'OTHER')}</strong><small>شبکه و نوع سرویس</small></div>${badge(String(g._count._all),'info')}</div>`).join('')}</div></div>`}; }
  const services=await prisma.service.findMany({where:{category:ServiceCategory.SOCIAL},include:{routes:{include:{provider:true}}},orderBy:[{enabled:'desc'},{sortOrder:'asc'}],take:300});
  return {tabs:moduleTabs,body:`<div class="card"><div class="card-head"><h2>Routing و Failover</h2><span class="muted">اولویت کمتر زودتر استفاده می‌شود</span></div><div class="table-wrap"><table class="table"><thead><tr><th>سرویس VELIXEO</th><th>Provider</th><th>Provider Service ID</th><th>اولویت</th><th>Markup</th><th>Sync</th></tr></thead><tbody>${services.flatMap(s=>s.routes.map(r=>`<tr><td>${esc(s.titleFa)}</td><td>${esc(r.provider.name)}</td><td class="code">${esc(r.providerServiceCode)}</td><td>${r.priority}</td><td>${esc((r.markupPercent??r.provider.defaultMarkupPercent).toString())}%</td><td>${faDate(r.lastSyncedAt)}</td></tr>`)).join('')||'<tr><td colspan="6" class="empty">Route ندارد.</td></tr>'}</tbody></table></div></div>`};
}

async function virtualPage(prisma:PrismaClient,tab:string,q:string,edit:string) {
  const baseTabs=[['overview','نمای کلی'],['providers','ارائه‌دهندگان'],['services','سرویس‌ها'],['countries','کشورها'],['pricing','قیمت‌گذاری'],['orders','سفارش‌ها'],['logs','API Logs']] as [string,string][];
  if(!['countries','pricing'].includes(tab)) { const r=await providerModule(prisma,'virtual',ServiceCategory.VIRTUAL_NUMBER,ProviderKind.VIRTUAL_NUMBER,tab,q,edit); return {tabs:tabs('virtual',tab,baseTabs),body:r.body}; }
  const providers=await prisma.provider.findMany({where:{kind:ProviderKind.VIRTUAL_NUMBER},orderBy:{priority:'asc'}});
  const settings=await prisma.systemSetting.findMany({where:{OR:[{key:'virtual.enabledCountries'},{key:{startsWith:'virtual.provider.'}}]},orderBy:{key:'asc'}});
  if(tab==='countries') { const row=settings.find(s=>s.key==='virtual.enabledCountries'); return {tabs:tabs('virtual',tab,baseTabs),body:`<div class="grid equal"><div class="card"><div class="card-head"><h2>کشورهای فعال</h2><span class="muted">خالی = همه کشورها</span></div><form method="post" action="/admin/virtual-numbers/countries" data-v3-return="virtual&tab=countries"><div class="field"><label>Country codes با کاما</label><textarea class="code" name="countries" placeholder="afghanistan, germany, england">${esc(Array.isArray(row?.value)?row?.value.join(', '):'')}</textarea></div><button class="btn">ذخیره کشورها</button></form></div><div class="card"><div class="card-head"><h2>Smart Buy</h2>${badge('Provider Hidden','ok')}</div><p class="muted">اپلیکیشن می‌تواند Best Rate، Low Price یا Any Operator را انتخاب کند. Provider واقعی در پاسخ مشتری نمایش داده نمی‌شود.</p></div></div>`}; }
  return {tabs:tabs('virtual',tab,baseTabs),body:`<div class="card"><div class="card-head"><h2>نرخ تبدیل Provider → AFN</h2><span class="muted">قیمت نهایی = Cost × FX × Markup</span></div><div class="grid equal">${providers.map(p=>{const s=settings.find(x=>x.key===`virtual.provider.${p.id}.afnPerUnit`);const v=typeof s?.value==='number'||typeof s?.value==='string'?String(s.value):'';return `<form class="card" style="box-shadow:none" method="post" action="/admin/virtual-numbers/provider-rate" data-v3-return="virtual&tab=pricing"><input type="hidden" name="providerId" value="${p.id}"><div class="card-head"><h3>${esc(p.name)}</h3>${badge(`${esc(p.defaultMarkupPercent.toString())}% markup`,'info')}</div><div class="field"><label>هر 1 واحد Provider چند AFN است؟</label><input name="afnPerUnit" inputmode="decimal" value="${esc(v)}" required></div><button class="btn">ذخیره نرخ</button></form>`}).join('')||'<div class="empty">Provider شماره مجازی ندارید.</div>'}</div></div>`};
}

function ordersTable(orders:any[]) { return `<div class="card"><div class="card-head"><h2>سفارش‌ها</h2>${badge(`${orders.length} مورد`,'info')}</div><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>کاربر</th><th>سرویس</th><th>Provider</th><th>مبلغ</th><th>وضعیت</th><th>زمان</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${shortId(o.id)}</td><td>${esc(o.user?.fullName||o.user?.email||o.user?.phone||'—')}</td><td><b>${esc(o.service?.titleFa||o.category)}</b><br><span class="muted">${esc(o.category)}</span></td><td>${esc(o.provider?.name||'—')}</td><td class="money">${afn(o.totalAmountAfn)}</td><td>${statusBadge(o.status)}</td><td>${faDate(o.createdAt)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">سفارشی وجود ندارد.</td></tr>'}</tbody></table></div></div>`; }

async function allOrders(prisma:PrismaClient,q:string) { const orders=await prisma.order.findMany({where:q?{OR:[{id:{contains:q,mode:'insensitive'}},{user:{OR:[{fullName:{contains:q,mode:'insensitive'}},{email:{contains:q,mode:'insensitive'}},{phone:{contains:q,mode:'insensitive'}}]}},{service:{OR:[{titleFa:{contains:q,mode:'insensitive'}},{titleEn:{contains:q,mode:'insensitive'}}]}}]}:{},include:{user:true,service:true,provider:true},orderBy:{createdAt:'desc'},take:200}); return ordersTable(orders); }

async function paymentsPage(prisma:PrismaClient) {
  const [payments,wallets,pending,paid]=await Promise.all([prisma.paymentTransaction.findMany({include:{user:true,provider:true},orderBy:{createdAt:'desc'},take:150}),prisma.wallet.aggregate({_sum:{balanceAfn:true}}),prisma.paymentTransaction.count({where:{status:PaymentStatus.PENDING}}),prisma.paymentTransaction.aggregate({where:{status:PaymentStatus.PAID},_sum:{amountAfn:true}})]);
  const base=(process.env.PUBLIC_BASE_URL||'').replace(/\/$/,''); const apiConfigured=Boolean(process.env.HESABPAY_API_KEY?.trim());
  return `<div class="stats"><div class="stat"><div class="stat-icon">${icon('wallet')}</div><div><small>موجودی کل کیف پول‌ها</small><strong>${afn(wallets._sum.balanceAfn||0n)}</strong></div></div><div class="stat"><div class="stat-icon">${icon('orders')}</div><div><small>پرداخت‌های Pending</small><strong>${pending}</strong></div></div><div class="stat"><div class="stat-icon">${icon('wallet')}</div><div><small>کل پرداخت موفق</small><strong>${afn(paid._sum.amountAfn||0n)}</strong></div></div><div class="stat"><div class="stat-icon">${icon('settings')}</div><div><small>HesabPay API</small><strong style="font-size:15px">${apiConfigured?'Configured':'Missing key'}</strong></div></div></div><div class="grid equal"><div class="card"><div class="card-head"><h2>درگاه HesabPay</h2>${apiConfigured?badge('آماده','ok'):badge('API Key ثبت نشده','warn')}</div><div class="field"><label>Environment</label><input readonly value="${esc(process.env.HESABPAY_ENVIRONMENT||'production')}"></div><div class="field"><label>Public Base URL</label><input class="code" readonly value="${esc(base||'Not configured')}"></div><div class="field"><label>Webhook endpoint</label><input class="code" readonly value="${esc(base?`${base}/api/v1/payments/hesabpay/webhook`:'Set PUBLIC_BASE_URL')}"></div><p class="muted">کلیدهای حساس در این صفحه نمایش داده نمی‌شوند.</p></div><div class="card"><div class="card-head"><h2>ساختار مالی</h2>${badge('Base Currency: AFN','info')}</div><p class="muted">اعتبار کیف پول، خرید، Refund و Manual adjustment همگی در Ledger ثبت می‌شوند. نمایش USD و تومان فقط بر پایه نرخ‌های Settings است.</p></div></div><div class="card"><div class="card-head"><h2>تراکنش‌های درگاه</h2><span class="muted">آخرین ۱۵۰ تراکنش</span></div><div class="table-wrap"><table class="table"><thead><tr><th>کاربر</th><th>Gateway</th><th>مبلغ</th><th>وضعیت</th><th>Reference</th><th>زمان</th></tr></thead><tbody>${payments.map(p=>`<tr><td>${esc(p.user.fullName||p.user.email||p.user.phone||'—')}</td><td>${esc(p.gateway)}</td><td class="money">${afn(p.amountAfn)}</td><td>${statusBadge(p.status)}</td><td class="code">${esc(p.externalId||p.referenceId||'—')}</td><td>${faDate(p.createdAt)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">تراکنشی نیست.</td></tr>'}</tbody></table></div></div>`;
}

async function couponsPage(prisma:PrismaClient) { const rows=await prisma.coupon.findMany({orderBy:{createdAt:'desc'},take:150}); return `<div class="grid"><div class="card"><div class="card-head"><h2>کدهای تخفیف</h2>${badge(`${rows.length} کد`,'info')}</div><div class="table-wrap"><table class="table"><thead><tr><th>کد</th><th>نوع</th><th>مقدار</th><th>استفاده</th><th>وضعیت</th></tr></thead><tbody>${rows.map(c=>`<tr><td class="code"><b>${esc(c.code)}</b></td><td>${esc(c.discountType)}</td><td>${esc(c.discountValue.toString())}</td><td>${c.usedCount}/${c.usageLimit??'∞'}</td><td>${c.active?badge('فعال','ok'):badge('خاموش','bad')}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-head"><h2>کد تخفیف جدید</h2><span class="muted">AFN یا درصد</span></div><form method="post" action="/admin/v3/coupon"><div class="form-grid"><div class="field"><label>Code</label><input class="code" name="code" required></div><div class="field"><label>عنوان</label><input name="title"></div><div class="field"><label>نوع</label><select name="discountType"><option>FIXED_AFN</option><option>PERCENT</option></select></div><div class="field"><label>مقدار</label><input name="discountValue" inputmode="decimal" required></div><div class="field"><label>حداقل سفارش AFN</label><input name="minOrderAfn" type="number" value="0"></div><div class="field"><label>حد استفاده</label><input name="usageLimit" type="number"></div></div><label class="check"><input type="checkbox" name="active" checked> فعال باشد</label><button class="btn">ساخت Coupon</button></form></div></div>`; }

async function bannersPage(prisma:PrismaClient) { const rows=await prisma.banner.findMany({orderBy:[{enabled:'desc'},{sortOrder:'asc'}]}); return `<div class="grid"><div class="card"><div class="card-head"><h2>بنرهای اپلیکیشن</h2>${badge(`${rows.length} بنر`,'info')}</div>${rows.map(b=>`<div class="provider-row" style="grid-template-columns:50px 1fr auto"><div style="width:48px;height:34px;border-radius:7px;background:#eef5fb url('${esc(b.imageUrl)}') center/cover"></div><div><strong>${esc(b.titleFa||b.titleEn||b.placement)}</strong><small>${esc(b.placement)} · ${esc(b.actionUrl||'بدون لینک')}</small></div>${b.enabled?badge('فعال','ok'):badge('خاموش','bad')}</div>`).join('')||'<div class="empty">بنری نیست.</div>'}</div><div class="card"><div class="card-head"><h2>بنر جدید</h2><span class="muted">CTA می‌تواند Deep Link باشد</span></div><form method="post" action="/admin/v3/banner"><div class="field"><label>Placement</label><select name="placement">${Object.values(BannerPlacement).map(x=>`<option>${x}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label>عنوان فارسی</label><input name="titleFa"></div><div class="field"><label>عنوان انگلیسی</label><input name="titleEn"></div></div><div class="field"><label>Image URL</label><input class="code" name="imageUrl" required></div><div class="field"><label>Action URL / Deep Link</label><input class="code" name="actionUrl" placeholder="velixeo://social"></div><div class="field"><label>ترتیب</label><input name="sortOrder" type="number" value="100"></div><label class="check"><input type="checkbox" name="enabled" checked> فعال</label><button class="btn">ساخت بنر</button></form></div></div>`; }

async function notificationsPage(prisma:PrismaClient) { const rows=await prisma.notification.findMany({include:{user:true},orderBy:{createdAt:'desc'},take:100}); return `<div class="grid"><div class="card"><div class="card-head"><h2>اعلان‌های اخیر</h2>${badge(`${rows.length}`,'info')}</div>${rows.map(n=>`<div class="provider-row" style="grid-template-columns:1fr auto"><div><strong>${esc(n.titleFa)}</strong><small>${esc(n.audience)} · ${faDate(n.publishAt)}</small></div>${n.enabled?badge('فعال','ok'):badge('خاموش','bad')}</div>`).join('')||'<div class="empty">اعلانی نیست.</div>'}</div><div class="card"><div class="card-head"><h2>ارسال اعلان</h2><span class="muted">عمومی یا برای یک User ID</span></div><form method="post" action="/admin/v3/notification"><div class="form-grid"><div class="field"><label>Audience</label><select name="audience"><option>ALL</option><option>USER</option></select></div><div class="field"><label>User UUID (اختیاری)</label><input class="code" name="userId"></div><div class="field"><label>عنوان فارسی</label><input name="titleFa" required></div><div class="field"><label>Title English</label><input name="titleEn" required></div></div><div class="field"><label>متن فارسی</label><textarea name="bodyFa" required></textarea></div><div class="field"><label>English body</label><textarea name="bodyEn" required></textarea></div><button class="btn">ثبت اعلان</button></form></div></div>`; }

async function supportPage(prisma:PrismaClient,ticketId:string) { const rows=await prisma.supportTicket.findMany({include:{user:true},orderBy:{lastMessageAt:'desc'},take:100}); const selected=ticketId?await prisma.supportTicket.findUnique({where:{id:ticketId},include:{user:true,messages:{include:{senderUser:true},orderBy:{createdAt:'asc'}}}}):null; return `<div class="grid"><div class="card"><div class="card-head"><h2>تیکت‌ها</h2>${badge(`${rows.length}`,'info')}</div>${rows.map(t=>`<a href="${url('support',`&ticket=${t.id}`)}" class="provider-row" style="grid-template-columns:1fr auto;text-decoration:none"><div><strong>${esc(t.subject)}</strong><small>${esc(t.user.fullName||t.user.email||'—')} · ${faDate(t.lastMessageAt)}</small></div>${statusBadge(t.status)}</a>`).join('')||'<div class="empty">تیکتی نیست.</div>'}</div><div class="card">${selected?`<div class="card-head"><div><h2>${esc(selected.subject)}</h2><span class="muted">${esc(selected.user.fullName||selected.user.email||'—')}</span></div>${statusBadge(selected.status)}</div><div style="max-height:420px;overflow:auto">${selected.messages.map(m=>`<div style="margin:8px 0;padding:10px 12px;border-radius:11px;background:${m.isAdmin?'#eaf5ff':'#f6f8fb'}"><b style="font-size:10px">${m.isAdmin?'مدیر':esc(m.senderUser?.fullName||'کاربر')}</b><div style="font-size:11px;margin-top:5px;white-space:pre-wrap">${esc(m.content)}</div><small class="muted">${faDate(m.createdAt)}</small></div>`).join('')}</div><form method="post" action="/admin/v3/support/reply"><input type="hidden" name="ticketId" value="${selected.id}"><div class="field"><label>پاسخ</label><textarea name="content" required></textarea></div><div class="form-grid"><div class="field"><label>وضعیت بعد از پاسخ</label><select name="status">${Object.values(SupportStatus).map(s=>`<option ${s==='PENDING_USER'?'selected':''}>${s}</option>`).join('')}</select></div><div style="display:flex;align-items:end"><button class="btn" style="width:100%;margin-bottom:10px">ارسال پاسخ</button></div></div></form>`:'<div class="empty">یک تیکت را انتخاب کن.</div>'}</div></div>`; }

async function settingsPage(prisma:PrismaClient) { const rates=await prisma.exchangeRate.findMany({orderBy:{code:'asc'}}); const get=(c:string)=>rates.find(r=>r.code===c)?.afnPerUnit.toString()||''; return `<div class="grid equal"><div class="card"><div class="card-head"><h2>نرخ ارز</h2>${badge('Base: AFN','info')}</div><p class="muted">USD و تومان فقط برای نمایش معادل قیمت‌اند؛ حسابداری اصلی AFN است.</p><form method="post" action="/admin/v3/rate"><div class="field"><label>1 USD = چند AFN</label><input name="usd" inputmode="decimal" value="${esc(get('USD'))}" required></div><div class="field"><label>1 TOMAN = چند AFN</label><input name="toman" inputmode="decimal" value="${esc(get('TOMAN'))}" required></div><button class="btn">ذخیره نرخ‌ها</button></form></div><div class="card"><div class="card-head"><h2>وضعیت Production</h2><span class="muted">Secrets نمایش داده نمی‌شوند</span></div><div class="provider-row" style="grid-template-columns:1fr auto"><div><strong>Provider encryption</strong><small>ADMIN_SECRET_ENCRYPTION_KEY</small></div>${providerSecretEncryptionConfigured()?badge('Configured','ok'):badge('Missing','bad')}</div><div class="provider-row" style="grid-template-columns:1fr auto"><div><strong>HesabPay API</strong><small>HESABPAY_API_KEY</small></div>${process.env.HESABPAY_API_KEY?badge('Configured','ok'):badge('Missing','warn')}</div><div class="provider-row" style="grid-template-columns:1fr auto"><div><strong>Public Base URL</strong><small class="code">${esc(process.env.PUBLIC_BASE_URL||'Not set')}</small></div>${process.env.PUBLIC_BASE_URL?badge('OK','ok'):badge('Missing','warn')}</div></div></div>`; }

async function auditPage(prisma:PrismaClient) { const rows=await prisma.adminAuditLog.findMany({include:{adminUser:true},orderBy:{createdAt:'desc'},take:250}); return `<div class="card"><div class="card-head"><h2>Audit Log</h2>${badge(`${rows.length} رویداد اخیر`,'info')}</div><div class="table-wrap"><table class="table"><thead><tr><th>زمان</th><th>مدیر</th><th>Action</th><th>Entity</th><th>خلاصه</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${faDate(r.createdAt)}</td><td>${esc(r.adminUser.fullName||r.adminUser.email||'ADMIN')}</td><td class="code">${esc(r.action)}</td><td>${esc(r.entityType)} ${r.entityId?shortId(r.entityId):''}</td><td>${esc(r.summary)}</td></tr>`).join('')}</tbody></table></div></div>`; }

export function registerAdminV3(app:FastifyInstance,prisma:PrismaClient,resolveAdmin:AdminResolver) {
  app.get('/admin/v3',async(request,reply)=>{ const admin=await requireAdmin(request,reply,resolveAdmin); if(!admin)return; const state=queryState(request); let body=''; let tabHtml=''; try { if(state.section==='dashboard')body=await dashboard(prisma); else if(state.section==='users')body=await usersPage(prisma,state.q,state.edit); else if(state.section==='social'){const r=await socialPage(prisma,state.tab,state.q,state.edit);body=r.body;tabHtml=r.tabs;} else if(state.section==='virtual'){const r=await virtualPage(prisma,state.tab,state.q,state.edit);body=r.body;tabHtml=r.tabs;} else if(state.section==='premium'){const r=await providerModule(prisma,'premium',ServiceCategory.PREMIUM,ProviderKind.PREMIUM,state.tab,state.q,state.edit);body=r.body;tabHtml=r.tabs;} else if(state.section==='topup'){const r=await providerModule(prisma,'topup',ServiceCategory.MOBILE_TOPUP,ProviderKind.TOPUP,state.tab,state.q,state.edit);body=r.body;tabHtml=r.tabs;} else if(state.section==='accounts'){const r=await providerModule(prisma,'accounts',ServiceCategory.DIGITAL_ACCOUNT,ProviderKind.GENERIC,state.tab,state.q,state.edit);body=r.body;tabHtml=r.tabs;} else if(state.section==='promotions'){const r=await providerModule(prisma,'promotions',ServiceCategory.PROMOTION,ProviderKind.GENERIC,state.tab,state.q,state.edit);body=r.body;tabHtml=r.tabs;} else if(state.section==='orders')body=await allOrders(prisma,state.q); else if(state.section==='payments')body=await paymentsPage(prisma); else if(state.section==='coupons')body=await couponsPage(prisma); else if(state.section==='banners')body=await bannersPage(prisma); else if(state.section==='notifications')body=await notificationsPage(prisma); else if(state.section==='support')body=await supportPage(prisma,state.ticket); else if(state.section==='settings')body=await settingsPage(prisma); else if(state.section==='audit')body=await auditPage(prisma); return reply.type('text/html; charset=utf-8').send(shell({admin,section:state.section,body,tabs:tabHtml,message:state.msg,error:state.err})); } catch(error){request.log.error(error); return reply.type('text/html; charset=utf-8').send(shell({admin,section:state.section,body:'<div class="card"><div class="empty">خطا در بارگذاری این بخش. جزئیات در Server Log ثبت شد.</div></div>',tabs:tabHtml,message:error instanceof Error?error.message:'load_failed',error:true}));} });

  app.post('/admin/v3/provider/save',async(request,reply)=>{const admin=await requireAdmin(request,reply,resolveAdmin);if(!admin)return;const b=request.body as AnyBody;const section=String(b.section||'social') as Section;try{const id=text(b,'providerId');const kind=String(b.kind) as ProviderKind;const name=text(b,'name'),slug=text(b,'slug').toLowerCase(),baseUrl=text(b,'baseUrl');if(!name||!slug||!Object.values(ProviderKind).includes(kind))throw new Error('invalid_provider');const data={name,slug,kind,baseUrl:baseUrl||null,priority:int(b.priority,100),defaultMarkupPercent:new Prisma.Decimal(text(b,'markup')||'0'),timeoutSeconds:Math.max(5,Math.min(120,int(b.timeout,30))),notes:text(b,'notes')||null,enabled:checked(b,'enabled')};const p=id?await prisma.provider.update({where:{id},data}):await prisma.provider.create({data});await audit(prisma,admin.id,id?'PROVIDER_UPDATE':'PROVIDER_CREATE','Provider',p.id,`${p.name} (${p.kind})`);return reply.code(303).redirect(url(section,`&tab=providers&edit=${p.id}&msg=${encodeURIComponent('Provider ذخیره شد')}`));}catch(e){return reply.code(303).redirect(url(section,`&tab=providers&err=1&msg=${encodeURIComponent(e instanceof Error?e.message:'invalid')}`));}});
  app.post('/admin/v3/provider/secret',async(request,reply)=>{const admin=await requireAdmin(request,reply,resolveAdmin);if(!admin)return;const b=request.body as AnyBody;const section=String(b.section||'social') as Section;try{if(!providerSecretEncryptionConfigured())throw new Error('کلید رمزگذاری سرور تنظیم نشده است');const providerId=text(b,'providerId'),secret=text(b,'secret');if(!providerId||!secret)throw new Error('secret_required');const encrypted=encryptProviderSecret(secret);const p=await prisma.provider.update({where:{id:providerId},data:encrypted});await audit(prisma,admin.id,'PROVIDER_SECRET_UPDATE','Provider',p.id,`Secret updated for ${p.name}`);return reply.code(303).redirect(url(section,`&tab=providers&edit=${p.id}&msg=${encodeURIComponent('API Key به صورت رمزگذاری‌شده ذخیره شد')}`));}catch(e){return reply.code(303).redirect(url(section,`&tab=providers&err=1&msg=${encodeURIComponent(e instanceof Error?e.message:'secret_failed')}`));}});
  app.post('/admin/v3/social/sync',async(request,reply)=>{const admin=await requireAdmin(request,reply,resolveAdmin);if(!admin)return;const providerId=text(request.body as AnyBody,'providerId');try{const r=await syncSocialProviderCatalog(prisma,providerId);await audit(prisma,admin.id,'SOCIAL_PROVIDER_SYNC','Provider',providerId,`Synced ${r.total} SMM services`,r as unknown as Prisma.InputJsonValue);return reply.code(303).redirect(url('social',`&tab=services&msg=${encodeURIComponent(`Sync کامل شد: ${r.total} سرویس`)}`));}catch(e){return reply.code(303).redirect(url('social',`&tab=providers&err=1&msg=${encodeURIComponent(e instanceof Error?e.message:'sync_failed')}`));}});
  app.post('/admin/v3/service/toggle',async(request,reply)=>{const admin=await requireAdmin(request,reply,resolveAdmin);if(!admin)return;const b=request.body as AnyBody;const serviceId=text(b,'serviceId'),section=String(b.section||'social') as Section;const s=await prisma.service.update({where:{id:serviceId},data:{enabled:String(b.enabled)==='1'}});await audit(prisma,admin.id,'SERVICE_TOGGLE','Service',s.id,`${s.titleEn}: ${s.enabled?'enabled':'disabled'}`);return reply.code(303).redirect(url(section,'&tab=services&msg=وضعیت سرویس ذخیره شد'));});
  app.post('/admin/v3/user/status',async(request,reply)=>{const admin=await requireAdmin(request,reply,resolveAdmin);if(!admin)return;const b=request.body as AnyBody;const userId=text(b,'userId');if(userId===admin.id)return reply.code(303).redirect(url('users',`&edit=${userId}&err=1&msg=${encodeURIComponent('حساب مدیر فعلی محافظت شده است')}`));const role=String(b.role) as UserRole,status=String(b.status) as UserStatus;if(!Object.values(UserRole).includes(role)||!Object.values(UserStatus).includes(status))return reply.code(303).redirect(url('users','&err=1&msg=invalid'));const u=await prisma.user.update({where:{id:userId},data:{role,status}});await audit(prisma,admin.id,'USER_ACCESS_UPDATE','User',u.id,`${u.role}/${u.status}`);return reply.code(303).redirect(url('users',`&edit=${u.id}&msg=${encodeURIComponent('حساب کاربر ذخیره شد')}`));});
  app.post('/admin/v3/wallet',async(request,reply)=>{const admin=await requireAdmin(request,reply,resolveAdmin);if(!admin)return;const b=request.body as AnyBody;const userId=text(b,'userId'),reason=text(b,'reason');let amount:bigint;try{amount=BigInt(text(b,'amountAfn'));}catch{return reply.code(303).redirect(url('users',`&edit=${userId}&err=1&msg=invalid_amount`));}if(amount===0n||reason.length<3)return reply.code(303).redirect(url('users',`&edit=${userId}&err=1&msg=invalid`));try{const entry=await prisma.$transaction(async tx=>{const w=await tx.wallet.findUnique({where:{userId}});if(!w)throw new Error('wallet_not_found');const next=w.balanceAfn+amount;if(next<0n)throw new Error('insufficient_funds');await tx.wallet.update({where:{id:w.id},data:{balanceAfn:next}});return tx.walletEntry.create({data:{walletId:w.id,type:amount>0n?WalletEntryType.MANUAL_CREDIT:WalletEntryType.MANUAL_DEBIT,status:WalletEntryStatus.COMPLETED,amountAfn:amount,balanceAfterAfn:next,description:reason,referenceType:'ADMIN_ADJUSTMENT',referenceId:admin.id,idempotencyKey:`v3-${admin.id}-${Date.now()}-${randomBytes(5).toString('hex')}`}});},{isolationLevel:Prisma.TransactionIsolationLevel.Serializable});await audit(prisma,admin.id,'WALLET_MANUAL_ADJUST','WalletEntry',entry.id,`${amount} AFN — ${reason}`,{userId});return reply.code(303).redirect(url('users',`&edit=${userId}&msg=${encodeURIComponent('تغییر کیف پول ثبت شد')}`));}catch(e){return reply.code(303).redirect(url('users',`&edit=${userId}&err=1&msg=${encodeURIComponent(e instanceof Error?e.message:'wallet_failed')}`));}});
  app.post('/admin/v3/rate',async(request,reply)=>{const admin=await requireAdmin(request,reply,resolveAdmin);if(!admin)return;const b=request.body as AnyBody;try{for(const [code,key] of [['USD','usd'],['TOMAN','toman']] as const){const raw=text(b,key);if(!/^\d+(\.\d{1,8})?$/.test(raw))throw new Error(`invalid_${key}`);await prisma.exchangeRate.upsert({where:{code},update:{afnPerUnit:new Prisma.Decimal(raw)},create:{code,afnPerUnit:new Prisma.Decimal(raw)}});}await audit(prisma,admin.id,'EXCHANGE_RATES_UPDATE','ExchangeRate',null,`USD=${text(b,'usd')}, TOMAN=${text(b,'toman')}`);return reply.code(303).redirect(url('settings','&msg=نرخ‌ها ذخیره شد'));}catch(e){return reply.code(303).redirect(url('settings',`&err=1&msg=${encodeURIComponent(e instanceof Error?e.message:'invalid')}`));}});
  app.post('/admin/v3/coupon',async(request,reply)=>{const admin=await requireAdmin(request,reply,resolveAdmin);if(!admin)return;const b=request.body as AnyBody;try{const code=text(b,'code').toUpperCase(),discountType=String(b.discountType) as CouponDiscountType;const c=await prisma.coupon.create({data:{code,title:text(b,'title')||null,discountType,discountValue:new Prisma.Decimal(text(b,'discountValue')),minOrderAfn:BigInt(text(b,'minOrderAfn')||'0'),usageLimit:text(b,'usageLimit')?int(b.usageLimit):null,active:checked(b,'active')}});await audit(prisma,admin.id,'COUPON_CREATE','Coupon',c.id,c.code);return reply.code(303).redirect(url('coupons','&msg=Coupon ساخته شد'));}catch(e){return reply.code(303).redirect(url('coupons',`&err=1&msg=${encodeURIComponent(e instanceof Error?e.message:'coupon_failed')}`));}});
  app.post('/admin/v3/banner',async(request,reply)=>{const admin=await requireAdmin(request,reply,resolveAdmin);if(!admin)return;const b=request.body as AnyBody;try{const placement=String(b.placement) as BannerPlacement;const row=await prisma.banner.create({data:{placement,titleFa:text(b,'titleFa')||null,titleEn:text(b,'titleEn')||null,imageUrl:text(b,'imageUrl'),actionUrl:text(b,'actionUrl')||null,enabled:checked(b,'enabled'),sortOrder:int(b.sortOrder,100)}});await audit(prisma,admin.id,'BANNER_CREATE','Banner',row.id,row.titleFa||row.titleEn||row.placement);return reply.code(303).redirect(url('banners','&msg=بنر ساخته شد'));}catch(e){return reply.code(303).redirect(url('banners',`&err=1&msg=${encodeURIComponent(e instanceof Error?e.message:'banner_failed')}`));}});
  app.post('/admin/v3/notification',async(request,reply)=>{const admin=await requireAdmin(request,reply,resolveAdmin);if(!admin)return;const b=request.body as AnyBody;try{const audience=String(b.audience) as NotificationAudience,userId=text(b,'userId')||null;const row=await prisma.notification.create({data:{audience,userId:audience===NotificationAudience.USER?userId:null,titleFa:text(b,'titleFa'),titleEn:text(b,'titleEn'),bodyFa:text(b,'bodyFa'),bodyEn:text(b,'bodyEn'),enabled:true}});await audit(prisma,admin.id,'NOTIFICATION_CREATE','Notification',row.id,row.titleEn);return reply.code(303).redirect(url('notifications','&msg=اعلان ثبت شد'));}catch(e){return reply.code(303).redirect(url('notifications',`&err=1&msg=${encodeURIComponent(e instanceof Error?e.message:'notification_failed')}`));}});
  app.post('/admin/v3/support/reply',async(request,reply)=>{const admin=await requireAdmin(request,reply,resolveAdmin);if(!admin)return;const b=request.body as AnyBody;const ticketId=text(b,'ticketId'),content=text(b,'content'),status=String(b.status) as SupportStatus;try{await prisma.$transaction([prisma.supportMessage.create({data:{ticketId,senderUserId:admin.id,isAdmin:true,content}}),prisma.supportTicket.update({where:{id:ticketId},data:{status,lastMessageAt:new Date()}})]);await audit(prisma,admin.id,'SUPPORT_REPLY','SupportTicket',ticketId,content.slice(0,120));return reply.code(303).redirect(url('support',`&ticket=${ticketId}&msg=${encodeURIComponent('پاسخ ارسال شد')}`));}catch(e){return reply.code(303).redirect(url('support',`&ticket=${ticketId}&err=1&msg=${encodeURIComponent(e instanceof Error?e.message:'reply_failed')}`));}});
}
